import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        X, Y = map(int, input().split())
        if X >= Y:
            print(0)
            exit()
        else:
            print((Y - X) // 10 + 1)
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

# Test cases
print(solve("270 750"))  # Expected: 49
print(solve("80 94"))  # Expected: 2

